import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.CDU0sSpB.js";const p=JSON.parse('{"title":"4.2 Build the proactive inbox","description":"Gather suggestions where they are easy to judge and handle.","frontmatter":{"title":"4.2 Build the proactive inbox","description":"Gather suggestions where they are easy to judge and handle.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/stage-4/4-2.md","filePath":"en/delivery/stage-4/4-2.md","lastUpdated":1794017073000}'),r={name:"en/delivery/stage-4/4-2.md"};function n(s,e,l,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="_4-2-build-the-proactive-inbox" tabindex="-1">4.2 Build the proactive inbox <a class="header-anchor" href="#_4-2-build-the-proactive-inbox" aria-label="Permalink to &quot;4.2 Build the proactive inbox&quot;">​</a></h1><h2 id="current-status" tabindex="-1">Current status <a class="header-anchor" href="#current-status" aria-label="Permalink to &quot;Current status&quot;">​</a></h2><ul><li><strong>Implemented:</strong> A separate inbox shows suggestions by priority; accept, ignore, snooze, and convert-to-task are supported; accept only records a decision and convert only creates a queued task, without approving or replaying external actions.</li><li><strong>Still open:</strong> No multi-device or phone inbox, and system push and remote takeover remain unaccepted; the local web inbox, in-app toasts, optional desktop notifications, and the Feishu long connection currently distribute approval and suggestion summaries.</li></ul><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Gather proactive suggestions in one place the user can handle easily, so it is clear what matters, why it matters, and what the user needs to do.</p><h2 id="how-to-do-it" tabindex="-1">How to do it <a class="header-anchor" href="#how-to-do-it" aria-label="Permalink to &quot;How to do it&quot;">​</a></h2><ol><li>Create one proactive inbox grouped by importance and time; do not scatter suggestions across pages.</li><li>Each item shows the source, proposed action, expected impact, expected cost, and whether approval is needed.</li><li>Provide accept, ignore, remind later, and turn-into-task actions to avoid repeated interruption.</li><li>Support quiet hours, a daily limit, and batch handling so the user controls how often they are interrupted.</li><li>After the user ignores an item, do not rephrase and push it again; keep one record per event.</li><li>Test with real suggestions: the user can judge quickly and does not turn notifications off because there are too many.</li></ol>',7)])])}const g=t(r,[["render",n]]);export{p as __pageData,g as default};
